163	impl Config {
164	    /// Load configuration from file or create default
165	    /// If config doesn't exist, attempts to discover profiles from the repo manifest
166	    /// Automatically migrates old config versions to the current version.
167	    pub fn load_or_create(config_path: &Path) -> Result<Self> {
168	        if config_path.exists() {
169	            tracing::debug!("Loading config from: {:?}", config_path);
170	            let content = std::fs::read_to_string(config_path)
171	                .with_context(|| format!("Failed to read config file: {config_path:?}"))?;
172	            let mut config: Config =
173	                toml::from_str(&content).with_context(|| "Failed to parse config file")?;
174	
175	            // Migrate if needed
176	            if config.version < CURRENT_VERSION {
177	                let old_version = config.version;
178	                tracing::info!(
179	                    "Migrating config from v{} to v{}",
180	                    old_version,
181	                    CURRENT_VERSION
182	                );
183	                config = Self::migrate(config)?;
184	
185	                // Backup, save, cleanup
186	                crate::utils::migrate_file(config_path, old_version, "toml", || {
187	                    config.save(config_path)
188	                })?;
189	            }
190	
191	            // Set defaults for missing fields (for backward compatibility)
192	            if config.repo_name.is_empty() {
193	                config.repo_name = default_repo_name();
194	            }
195	            if config.default_branch.is_empty() {
196	                config.default_branch = default_branch_name();
197	            }
198	            // backup_enabled defaults to true if not present
199	            // (handled by serde default)
200	
201	            // If active_profile is empty and repo exists, try to set it from manifest
202	            if config.active_profile.is_empty() && config.repo_path.exists() {
203	                if let Ok(manifest) =
204	                    crate::utils::ProfileManifest::load_or_backfill(&config.repo_path)
205	                {
206	                    if let Some(first_profile) = manifest.profiles.first() {
207	                        config.active_profile = first_profile.name.clone();
208	                        config.save(config_path)?;
209	                    }
210	                }
211	            }
212	
213	            tracing::info!("Config loaded successfully");
214	            Ok(config)
215	        } else {
216	            // Config doesn't exist - create default
217	            tracing::info!(
218	                "Config not found, creating default config at: {:?}",
219	                config_path
220	            );
221	            let mut config = Self::default();
222	
223	            // Try to discover active profile from the repo manifest if repo_path exists
224	            if config.repo_path.exists() {
225	                if let Ok(manifest) =
226	                    crate::utils::ProfileManifest::load_or_backfill(&config.repo_path)
227	                {
228	                    if let Some(first_profile) = manifest.profiles.first() {
229	                        config.active_profile = first_profile.name.clone();
230	                    }
231	                }
232	            }
233	
234	            config.save(config_path)?;
235	            Ok(config)
236	        }
237	    }
238	
239	    /// Save configuration to file with secure permissions.
240	    /// Uses atomic write (temp file + rename) to prevent corruption on crash.
241	    pub fn save(&self, config_path: &Path) -> Result<()> {
242	        let content = toml::to_string_pretty(self).with_context(|| "Failed to serialize config")?;
243	        let temp_path = config_path.with_extension("toml.tmp");
244	
245	        if let Some(parent) = config_path.parent() {
246	            std::fs::create_dir_all(parent)
247	                .with_context(|| format!("Failed to create config directory: {parent:?}"))?;
248	        }
249	
250	        // Write to temp file first
251	        std::fs::write(&temp_path, &content)
252	            .with_context(|| format!("Failed to write temp config: {temp_path:?}"))?;
253	
254	        // Set secure permissions on temp file (600: owner read/write only)
255	        #[cfg(unix)]
256	        {
257	            use std::os::unix::fs::PermissionsExt;
258	            let mut perms = std::fs::metadata(&temp_path)
259	                .with_context(|| format!("Failed to get file metadata: {temp_path:?}"))?
260	                .permissions();
261	            perms.set_mode(0o600);
262	            std::fs::set_permissions(&temp_path, perms)
263	                .with_context(|| format!("Failed to set file permissions: {temp_path:?}"))?;
264	        }
265	
266	        // Atomic rename (on POSIX systems)
267	        std::fs::rename(&temp_path, config_path)
268	            .with_context(|| format!("Failed to rename temp config to {config_path:?}"))?;
269	
270	        Ok(())
271	    }
272	
273	    /// Check if the repository is configured (either GitHub or Local mode)
274	    #[must_use]
275	    pub fn is_repo_configured(&self) -> bool {
276	        match self.repo_mode {
277	            RepoMode::GitHub => self.github.is_some(),
278	            RepoMode::Local => self.repo_path.join(".git").exists(),
279	        }
280	    }
281	
282	    /// Reset config to unconfigured state
283	    /// Used when setup fails partway through to ensure clean retry
284	    pub fn reset_to_unconfigured(&mut self) {
285	        self.github = None;
286	        self.active_profile = String::new();
287	        self.profile_activated = false;
288	        self.repo_name = default_repo_name();
289	        // Keep repo_path as the default location - it will be recreated on next setup
290	        // Keep other settings like backup_enabled, theme, keymap
291	    }
292	
293	    /// Get GitHub token from environment variable or config
294	    /// Priority: `DOTSTATE_GITHUB_TOKEN` env var > config token
295	    /// Returns None if neither is set
296	    pub fn get_github_token(&self) -> Option<String> {
297	        // First, check environment variable
298	        if let Ok(token) = std::env::var("DOTSTATE_GITHUB_TOKEN") {
299	            if !token.is_empty() {
300	                tracing::debug!(
301	                    "Using GitHub token from DOTSTATE_GITHUB_TOKEN environment variable"
302	                );
303	                return Some(token);
304	            }
305	        }
306	
307	        // Fall back to config token
308	        self.github
309	            .as_ref()
310	            .and_then(|gh| gh.token.as_ref())
311	            .cloned()
312	    }
313	
314	    /// Get the icon set based on config value
315	    /// Returns the configured icon set, or auto-detects if set to "auto"
316	    #[must_use]
317	    pub fn get_icon_set(&self) -> crate::icons::IconSet {
318	        use crate::icons::IconSet;
319	
320	        match self.icon_set.to_lowercase().as_str() {
321	            "nerd" | "nerdfont" | "nerdfonts" => IconSet::NerdFonts,
322	            "unicode" => IconSet::Unicode,
323	            "emoji" => IconSet::Emoji,
324	            "ascii" | "plain" => IconSet::Ascii,
325	            _ => IconSet::detect(), // Auto-detect or fallback to detection
326	        }
327	    }
