329	    // Profile-related methods removed - use ProfileManifest directly
330	    // Helper method removed as it's not used - profiles are accessed via App::get_profiles() instead
331	
332	    // ==================== Migration Methods ====================
333	
334	    /// Run all necessary migrations to bring config to current version.
335	    fn migrate(mut config: Self) -> Result<Self> {
336	        if config.version == 0 {
337	            config = Self::migrate_v0_to_v1(config)?;
338	        }
339	        // Future migrations:
340	        // if config.version == 1 { config = Self::migrate_v1_to_v2(config)?; }
341	        Ok(config)
342	    }
343	
344	    /// Migrate from v0 (no version field) to v1.
345	    /// This is a no-op migration that just sets the version field.
346	    fn migrate_v0_to_v1(mut config: Self) -> Result<Self> {
347	        tracing::debug!("Migrating config v0 -> v1");
348	        config.version = 1;
349	        Ok(config)
350	    }
351	}
