30	/// Guard that restores environment variables when dropped.
31	struct EnvGuard {
32	    old_home: Option<String>,
33	    old_config: Option<String>,
34	    old_backup: Option<String>,
35	    #[allow(dead_code)]
36	    lock: std::sync::MutexGuard<'static, ()>,
