39	impl Drop for EnvGuard {
40	    fn drop(&mut self) {
41	        // Restore original env vars
42	        match &self.old_home {
43	            Some(v) => std::env::set_var("DOTSTATE_TEST_HOME", v),
44	            None => std::env::remove_var("DOTSTATE_TEST_HOME"),
45	        }
46	        match &self.old_config {
47	            Some(v) => std::env::set_var("DOTSTATE_TEST_CONFIG_DIR", v),
48	            None => std::env::remove_var("DOTSTATE_TEST_CONFIG_DIR"),
49	        }
50	        match &self.old_backup {
51	            Some(v) => std::env::set_var("DOTSTATE_TEST_BACKUP_DIR", v),
52	            None => std::env::remove_var("DOTSTATE_TEST_BACKUP_DIR"),
53	        }
54	    }
55	}
